from itertools import product

# 群元素用索引表示: 0=e, 1=x3, 2=x1, 3=x2
# 乘法表 (行 * 列)
table = [
    [0, 1, 2, 3],  # e
    [1, 0, 3, 2],  # x3
    [2, 3, 0, 1],  # x1
    [3, 2, 1, 0],  # x2
]

names = ['e', 'x3', 'x1', 'x2']

# 求逆元
def inv(a):
    for b in range(4):
        if table[a][b] == 0:
            return b

# 共轭: g a g^{-1}
def conj(g, a):
    return table[g][table[a][inv(g)]]

# 求每个元素的共轭类
for a in range(4):
    conj_class = set()
    for g in range(4):
        conj_class.add(conj(g, a))
    conj_class_names = sorted([names[x] for x in conj_class])
    print(f"conj class of {names[a]}: {conj_class_names}")

# 验证群是交换群
abelian = True
for a, b in product(range(4), repeat=2):
    if table[a][b] != table[b][a]:
        abelian = False
print(f"\nAbelian: {abelian}")
